class Solution:
    def findSubsequences(self, nums: list[int]) -> list[list[int]]:
        out=[];path=[]
        def dfs(start):
            if len(path)>=2:out.append(path[:])
            used=set()
            for i in range(start,len(nums)):
                if nums[i] in used:continue
                if not path or nums[i]>=path[-1]:
                    used.add(nums[i]);path.append(nums[i]);dfs(i+1);path.pop()
        dfs(0);return out

import java.util.*;
class Solution {
    private int[] nums;private List<List<Integer>>out;private List<Integer>path;
    public List<List<Integer>> findSubsequences(int[] nums){this.nums=nums;out=new ArrayList<>();path=new ArrayList<>();dfs(0);return out;}
    private void dfs(int start){if(path.size()>=2)out.add(new ArrayList<>(path));Set<Integer>used=new HashSet<>();for(int i=start;i<nums.length;i++)if((path.isEmpty()||nums[i]>=path.get(path.size()-1))&&used.add(nums[i])){path.add(nums[i]);dfs(i+1);path.remove(path.size()-1);}}
}

class Solution:
    def findTargetSumWays(self, nums: list[int], target: int) -> int:
        total=sum(nums)
        if abs(target)>total or (total+target)%2:return 0
        goal=(total+target)//2;dp=[0]*(goal+1);dp[0]=1
        for x in nums:
            for s in range(goal,x-1,-1):dp[s]+=dp[s-x]
        return dp[goal]

class Solution {
    public int findTargetSumWays(int[] nums,int target) {
        int total=0;for(int x:nums)total+=x;if(Math.abs(target)>total||((total+target)&1)!=0)return 0;
        int goal=(total+target)/2;int[]dp=new int[goal+1];dp[0]=1;
        for(int x:nums)for(int s=goal;s>=x;s--)dp[s]+=dp[s-x];return dp[goal];
    }
}

class Solution:
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        stack=[];nxt={}
        for x in nums2:
            while stack and stack[-1]<x:nxt[stack.pop()]=x
            stack.append(x)
        return [nxt.get(x,-1) for x in nums1]

