class Solution {
    public int[] nextGreaterElement(int[] nums1,int[] nums2) {
        Deque<Integer>st=new ArrayDeque<>();Map<Integer,Integer>next=new HashMap<>();
        for(int x:nums2){while(!st.isEmpty()&&st.peek()<x)next.put(st.pop(),x);st.push(x);}
        int[]out=new int[nums1.length];for(int i=0;i<nums1.length;i++)out[i]=next.getOrDefault(nums1[i],-1);return out;
    }
}

class Solution:
    def findDiagonalOrder(self, mat: list[list[int]]) -> list[int]:
        if not mat or not mat[0]:return []
        m,n=len(mat),len(mat[0]);out=[]
        for d in range(m+n-1):
            vals=[]
            r=max(0,d-n+1);c=d-r
            while r<m and c>=0:
                vals.append(mat[r][c]);r+=1;c-=1
            if d%2==0:vals.reverse()
            out.extend(vals)
        return out

import java.util.*;
class Solution {
    public int[] findDiagonalOrder(int[][] mat) {
        if(mat.length==0||mat[0].length==0)return new int[0];int m=mat.length,n=mat[0].length;int[]out=new int[m*n];int p=0;
        for(int d=0;d<m+n-1;d++){List<Integer>v=new ArrayList<>();int r=Math.max(0,d-n+1),c=d-r;while(r<m&&c>=0){v.add(mat[r++][c--]);}
            if(d%2==0)Collections.reverse(v);for(int x:v)out[p++]=x;
        }return out;
    }
}

