class Solution:
    def findMode(self, root):
        self.prev=None;self.count=0;self.best=0;self.out=[]
        def dfs(node):
            if not node:return
            dfs(node.left)
            if node.val==self.prev:self.count+=1
            else:self.prev=node.val;self.count=1
            if self.count>self.best:self.best=self.count;self.out=[node.val]
            elif self.count==self.best:self.out.append(node.val)
            dfs(node.right)
        dfs(root);return self.out

import java.util.*;
class Solution {
    private Integer prev;private int count,max;private List<Integer>modes;
    public int[] findMode(TreeNode root){prev=null;count=0;max=0;modes=new ArrayList<>();dfs(root);return modes.stream().mapToInt(Integer::intValue).toArray();}
    private void dfs(TreeNode n){if(n==null)return;dfs(n.left);if(prev!=null&&prev==n.val)count++;else{prev=n.val;count=1;}if(count>max){max=count;modes.clear();modes.add(n.val);}else if(count==max)modes.add(n.val);dfs(n.right);}
}

class Solution:
    def nextGreaterElements(self, nums: list[int]) -> list[int]:
        n=len(nums);ans=[-1]*n;stack=[]
        for i in range(2*n):
            idx=i%n
            while stack and nums[stack[-1]]<nums[idx]:ans[stack.pop()]=nums[idx]
            if i<n:stack.append(idx)
        return ans

import java.util.*;
class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n=nums.length;int[]ans=new int[n];Arrays.fill(ans,-1);Deque<Integer>st=new ArrayDeque<>();
        for(int i=0;i<2*n;i++){int idx=i%n;while(!st.isEmpty()&&nums[st.peek()]<nums[idx])ans[st.pop()]=nums[idx];if(i<n)st.push(idx);}return ans;
    }
}

class Solution:
    def convertToBase7(self, num: int) -> str:
        if num==0:return "0"
        sign='-' if num<0 else '';num=abs(num);out=[]
        while num:out.append(str(num%7));num//=7
        return sign+''.join(reversed(out))

class Solution {
    public String convertToBase7(int num) {
        if(num==0)return "0";boolean neg=num<0;long x=Math.abs((long)num);StringBuilder s=new StringBuilder();
        while(x>0){s.append(x%7);x/=7;}if(neg)s.append('-');return s.reverse().toString();
    }
}

class Solution:
    def findRelativeRanks(self, score: list[int]) -> list[str]:
        order=sorted(range(len(score)),key=lambda i:score[i],reverse=True);out=['']*len(score)
        labels=["Gold Medal","Silver Medal","Bronze Medal"]
        for rank,i in enumerate(order):
            out[i]=labels[rank] if rank<3 else str(rank+1)
        return out

import java.util.*;
class Solution {
    public String[] findRelativeRanks(int[] score) {
        Integer[]idx=new Integer[score.length];for(int i=0;i<idx.length;i++)idx[i]=i;Arrays.sort(idx,(a,b)->Integer.compare(score[b],score[a]));
        String[]out=new String[score.length];String[]medals={"Gold Medal","Silver Medal","Bronze Medal"};
        for(int r=0;r<idx.length;r++)out[idx[r]]=r<3?medals[r]:Integer.toString(r+1);return out;
    }
}

from collections import Counter
class Solution:
    def findFrequentTreeSum(self, root):
        if not root:return []
        counts=Counter()
        def dfs(node):
            if not node:return 0
            total=node.val+dfs(node.left)+dfs(node.right);counts[total]+=1;return total
        dfs(root);best=max(counts.values())
        return [s for s,c in counts.items() if c==best]

import java.util.*;
class Solution {
    private Map<Integer,Integer>counts;
    public int[] findFrequentTreeSum(TreeNode root) {
        if(root==null)return new int[0];counts=new HashMap<>();sum(root);int max=0;for(int c:counts.values())max=Math.max(max,c);List<Integer>out=new ArrayList<>();for(Map.Entry<Integer,Integer>e:counts.entrySet())if(e.getValue()==max)out.add(e.getKey());return out.stream().mapToInt(Integer::intValue).toArray();
    }
    private int sum(TreeNode n){if(n==null)return 0;int s=n.val+sum(n.left)+sum(n.right);counts.put(s,counts.getOrDefault(s,0)+1);return s;}
}
